import{_ as a,o as i,c as s,ag as t}from"./chunks/framework.DNyhUiu9.js";const u=JSON.parse('{"title":"Cloudflare setup","description":"Enable Cloudflare Email Sending, verify a domain, and create an API token.","frontmatter":{"title":"Cloudflare setup","description":"Enable Cloudflare Email Sending, verify a domain, and create an API token."},"headers":[],"relativePath":"packages/provider-email-cloudflare/guide/cloudflare-setup.md","filePath":"packages/provider-email-cloudflare/docs/guide/cloudflare-setup.md"}'),n={name:"packages/provider-email-cloudflare/guide/cloudflare-setup.md"};function o(r,e,l,d,p,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="cloudflare-setup" tabindex="-1">Cloudflare setup <a class="header-anchor" href="#cloudflare-setup" aria-label="Permalink to &quot;Cloudflare setup&quot;">​</a></h1><p>Everything that has to exist on the Cloudflare side before Strapi can send.</p><h2 id="_1-plan" tabindex="-1">1. Plan <a class="header-anchor" href="#_1-plan" aria-label="Permalink to &quot;1. Plan&quot;">​</a></h2><p>Email Sending (outbound to arbitrary recipients) requires the <strong>Workers Paid</strong> plan. On the Free plan you can only send to <a href="https://developers.cloudflare.com/email-service/configuration/email-routing-addresses/" target="_blank" rel="noreferrer">verified destination addresses</a> inside your own account.</p><p>Sending is 3,000 emails/month included, then $0.35 per 1,000 — see the <a href="https://developers.cloudflare.com/email-service/platform/pricing/" target="_blank" rel="noreferrer">pricing page</a>.</p><h2 id="_2-onboard-your-sending-domain" tabindex="-1">2. Onboard your sending domain <a class="header-anchor" href="#_2-onboard-your-sending-domain" aria-label="Permalink to &quot;2. Onboard your sending domain&quot;">​</a></h2><p>From the Cloudflare dashboard (Email Service → Email Sending), or with wrangler:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sending</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yourdomain.com</span></span></code></pre></div><p>Cloudflare then shows the DNS records to add (SPF + DKIM, and a verification record). Publish them at your DNS provider and wait for the domain to show as verified — until it is, sends fail with <code>E_SENDER_NOT_VERIFIED</code>-style errors, or <code>email.sending.error.authentication.forbidden</code> from the REST API.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The domain used in <code>settings.defaultFrom</code> must be the onboarded one. Any local part works (<code>no-reply@</code>, <code>orders@</code>, <code>support@</code>) once the domain itself is verified.</p></div><h2 id="_3-create-an-api-token" tabindex="-1">3. Create an API token <a class="header-anchor" href="#_3-create-an-api-token" aria-label="Permalink to &quot;3. Create an API token&quot;">​</a></h2><ol><li><a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">Create a Cloudflare API token</a> with the <strong>Email Sending</strong> permission (account-level), scoped to the account that owns your domain.</li><li>Copy the token — this becomes <code>CLOUDFLARE_API_TOKEN</code>.</li><li>Copy your <strong>account ID</strong> from the dashboard sidebar or any zone&#39;s overview page — this becomes <code>CLOUDFLARE_ACCOUNT_ID</code>.</li></ol><p>Never commit either value; keep them in <code>.env</code> / your secret manager. The provider only ever reads them from <code>providerOptions</code>.</p><h2 id="_4-test-outside-strapi" tabindex="-1">4. Test outside Strapi <a class="header-anchor" href="#_4-test-outside-strapi" aria-label="Permalink to &quot;4. Test outside Strapi&quot;">​</a></h2><p>Confirm the credentials work before wiring Strapi:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.cloudflare.com/client/v4/accounts/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLOUDFLARE_ACCOUNT_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/email/sending/send&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLOUDFLARE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;to&quot;: &quot;you@yourdomain.com&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;from&quot;: &quot;no-reply@yourdomain.com&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;subject&quot;: &quot;Cloudflare Email Sending works&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;html&quot;: &quot;&lt;p&gt;It works.&lt;/p&gt;&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;text&quot;: &quot;It works.&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>A <code>200</code> with <code>&quot;success&quot;: true</code> means the token and domain are good. Send to an address you actually control — bounces from invented addresses damage your sender reputation.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Continue with <a href="/pr-preview/pr-54/packages/provider-email-cloudflare/guide/configuration.html">Configuration</a>.</p>`,19)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
